{
  "name": "color-cli",
  "version": "0.1.0",
  "description": "Example Node.js CLI that detects terminal color support before printing colored text.",
  "type": "module",
  "bin": {
    "color-cli": "./bin/cli.js"
  },
  "main": "./src/colors.js",
  "exports": {
    ".": "./src/colors.js"
  },
  "files": [
    "bin",
    "src"
  ],
  "scripts": {
    "start": "node bin/cli.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}

const ANSI = {
  reset: 0,
  bold: 1,
  dim: 2,
  italic: 3,
  underline: 4,
  red: 31,
  green: 32,
  yellow: 33,
  blue: 34,
  magenta: 35,
  cyan: 36,
  white: 37,
  gray: 90,
};

/**
 * Determine the color level supported by `stream`.
 *
 * 0 = no color, 1 = 16 colors, 2 = 256 colors, 3 = truecolor (16m).
 *
 * Honors the `NO_COLOR` and `FORCE_COLOR` environment conventions and falls
 * back to the terminal's own TTY / color-depth detection.
 */
export function colorLevel(stream = process.stdout) {
  const { FORCE_COLOR, NO_COLOR, TERM } = process.env;

  if (NO_COLOR !== undefined && NO_COLOR !== '') return 0;

  if (FORCE_COLOR !== undefined && FORCE_COLOR !== '') {
    const n = Number.parseInt(FORCE_COLOR, 10);
    if (Number.isNaN(n) || n <= 0) return 0;
    if (n === 1) return 1;
    if (n === 2) return 2;
    return 3;
  }

  if (!stream || !stream.isTTY) return 0;
  if (TERM === 'dumb') return 0;

  if (typeof stream.getColorDepth === 'function') {
    const depth = stream.getColorDepth();
    if (depth >= 24) return 3;
    if (depth >= 8) return 2;
    if (depth >= 4) return 1;
    return 0;
  }

  if (typeof stream.hasColors === 'function' && stream.hasColors()) return 1;
  return 0;
}

export function supportsColor(stream = process.stdout) {
  return colorLevel(stream) > 0;
}

/**
 * Build a set of color helpers bound to `stream`. When the terminal does not
 * support color every helper becomes an identity function, so callers never
 * need to branch on `enabled` themselves.
 */
export function createColors(stream = process.stdout) {
  const level = colorLevel(stream);
  const enabled = level > 0;

  const wrap = (code) => (text) =>
    enabled ? `\x1b[${code}m${text}\x1b[${ANSI.reset}m` : String(text);

  const colors = { enabled, level };
  for (const [name, code] of Object.entries(ANSI)) {
    if (name === 'reset') continue;
    colors[name] = wrap(code);
  }
  return colors;
}

export default createColors();

#!/usr/bin/env node
import { createColors } from '../src/colors.js';

const colors = createColors(process.stdout);
const name = process.argv[2] ?? 'world';

console.log(colors.green(`Hello, ${name}!`));

if (colors.enabled) {
  console.log(colors.dim(`\u2713 color enabled (level ${colors.level})`));
} else {
  console.log('color disabled (not a TTY, or NO_COLOR is set)');
}

process.exitCode = 0;

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { colorLevel, supportsColor, createColors } from '../src/colors.js';

const tty = (depth) => ({
  isTTY: true,
  getColorDepth: () => depth,
});

const nonTty = { isTTY: false };

function withEnv(vars, fn) {
  const saved = {};
  for (const key of Object.keys(vars)) saved[key] = process.env[key];
  for (const [key, value] of Object.entries(vars)) {
    if (value === undefined) delete process.env[key];
    else process.env[key] = value;
  }
  try {
    return fn();
  } finally {
    for (const [key, value] of Object.entries(saved)) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
  }
}

test('empty env with no TTY disables color', () => {
  withEnv({ NO_COLOR: undefined, FORCE_COLOR: undefined }, () => {
    assert.equal(colorLevel(nonTty), 0);
    assert.equal(supportsColor(nonTty), false);
  });
});

test('a TTY without color depth still enables basic color', () => {
  withEnv({ NO_COLOR: undefined, FORCE_COLOR: undefined }, () => {
    assert.equal(colorLevel({ isTTY: true }), 1);
  });
});

test('maps terminal color depth to a level', () => {
  withEnv({ NO_COLOR: undefined, FORCE_COLOR: undefined }, () => {
    assert.equal(colorLevel(tty(1)), 0);
    assert.equal(colorLevel(tty(4)), 1);
    assert.equal(colorLevel(tty(8)), 2);
    assert.equal(colorLevel(tty(24)), 3);
  });
});

test('NO_COLOR wins over a color-capable TTY', () => {
  withEnv({ NO_COLOR: '1', FORCE_COLOR: undefined }, () => {
    assert.equal(colorLevel(tty(24)), 0);
  });
});

test('FORCE_COLOR enables color on a non-TTY', () => {
  withEnv({ NO_COLOR: undefined, FORCE_COLOR: '1' }, () => {
    assert.equal(colorLevel(nonTty), 1);
  });
});

test('FORCE_COLOR=0 disables color on a TTY', () => {
  withEnv({ NO_COLOR: undefined, FORCE_COLOR: '0' }, () => {
    assert.equal(colorLevel(tty(24)), 0);
  });
});

test('TERM=dumb disables color', () => {
  withEnv({ NO_COLOR: undefined, FORCE_COLOR: undefined, TERM: 'dumb' }, () => {
    assert.equal(colorLevel(tty(24)), 0);
  });
});

test('helpers wrap text when enabled and pass through when disabled', () => {
  withEnv({ NO_COLOR: undefined, FORCE_COLOR: '1' }, () => {
    assert.equal(createColors(nonTty).green('hi'), '\x1b[32mhi\x1b[0m');
  });
  withEnv({ NO_COLOR: undefined, FORCE_COLOR: '0' }, () => {
    assert.equal(createColors(tty(24)).green('hi'), 'hi');
  });
});

